#!/usr/bin/env python3
"""
Round 213o (culprits), 15 October 2026. Needs round 212o (round210o_212o_culprits.py).

The sky without painted stars; dead things round the Sun (working craft left
out); gravity assists and the Sun's gravity reach taken out; Solar Tech;
Antigravity under the space industry; gravity's fabric.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 213o (15 October)\n\nNeeds round 212o (guards on its heading). Tiles patch round213o_tiles.py\n(culprits-tiles-more), then refresh reach and sun. No app.js?v= bump;\nbodies.html is asked for as ?v=213.\n\n- Sky chart and sky globe: no painted stars behind them (the sky is itself a\n  map of starlight); the other views keep theirs.\n- Sun view: the objects row is "Dead probes, spent rocket stages and parts\n  orbiting the Sun"; craft still working (named on Wikipedia\'s List of active\n  Solar System probes, marked by scripts/sun.py) are left out and named in\n  the row. Gravity assists taken out (row, layer and code).\n- Sunlight\'s reach (was From the Sun): the Sun\'s pull rings and Oort bands\n  taken out with the Sun\'s gravity reach layer; says it looks outward, and\n  Light reaching Earth inward. Opens on the outermost ring (quarter-step\n  zoom), and a view laid out before its frame had a size is laid out again.\n- From Earth: Gravity\'s fabric (row fabric; layer gravity_fields): every body\n  with a published mass and place, its Hill sphere drawn round its mark\n  (measured against the smallest larger field holding it, else the larger\n  body pulling hardest); colour = how many fields cross (teal to cobalt to\n  plum), shading = all pulls summed; a click names the fields there.\n- Panel: To the Sun = objects, then Solar Tech (solar farms, solar panel\n  makers, Sunlight\'s reach, Light reaching Earth). The space industry gains\n  an Antigravity sub-heading (anti-gravity, gravity\'s fabric). The "Light,\n  anti-gravity and gravity assists" heading is gone.\n\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round213o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 212o" not in h.read_text(encoding="utf-8"):
        sys.exit("round213o: round 212o must be applied first (round210o_212o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round213o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round213o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round213o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
